7	import { useRef, useCallback } from 'react';
8	import type React from 'react';
9	import { Box, Text } from 'ink';
10	import { theme } from '../semantic-colors.js';
11	import type { ConsoleMessageItem } from '../types.js';
12	import {
13	  ScrollableList,
14	  type ScrollableListRef,
15	} from './shared/ScrollableList.js';
16	
17	interface DetailedMessagesDisplayProps {
18	  messages: ConsoleMessageItem[];
19	  maxHeight: number | undefined;
20	  width: number;
21	  hasFocus: boolean;
22	}
23	
24	const iconBoxWidth = 3;
25	
26	export const DetailedMessagesDisplay: React.FC<
27	  DetailedMessagesDisplayProps
28	> = ({ messages, maxHeight, width, hasFocus }) => {
29	  const scrollableListRef = useRef<ScrollableListRef<ConsoleMessageItem>>(null);
30	
31	  const borderAndPadding = 3;
32	
33	  const estimatedItemHeight = useCallback(
34	    (index: number) => {
35	      const msg = messages[index];
36	      if (!msg) {
37	        return 1;
38	      }
39	      const textWidth = width - borderAndPadding - iconBoxWidth;
40	      if (textWidth <= 0) {
41	        return 1;
42	      }
43	      const lines = Math.ceil((msg.content?.length || 1) / textWidth);
44	      return Math.max(1, lines);
45	    },
46	    [width, messages],
47	  );
48	
49	  if (messages.length === 0) {
50	    return null;
51	  }
52	
53	  return (
54	    <Box
55	      flexDirection="column"
56	      marginTop={1}
57	      borderStyle="round"
58	      borderColor={theme.border.default}
59	      paddingLeft={1}
60	      width={width}
61	      height={maxHeight}
62	      flexShrink={0}
63	      flexGrow={0}
64	      overflow="hidden"
65	    >
66	      <Box marginBottom={1}>
67	        <Text bold color={theme.text.primary}>
68	          Debug Console <Text color={theme.text.secondary}>(F12 to close)</Text>
69	        </Text>
70	      </Box>
71	      <Box height={maxHeight} width={width - borderAndPadding}>
72	        <ScrollableList
73	          ref={scrollableListRef}
74	          data={messages}
75	          renderItem={({ item: msg }: { item: ConsoleMessageItem }) => {
76	            let textColor = theme.text.primary;
77	            let icon = 'ℹ'; // Information source (ℹ)
78	
79	            switch (msg.type) {
80	              case 'warn':
81	                textColor = theme.status.warning;
82	                icon = '⚠'; // Warning sign (⚠)
83	                break;
84	              case 'error':
85	                textColor = theme.status.error;
86	                icon = '✖'; // Heavy multiplication x (✖)
87	                break;
88	              case 'debug':
89	                textColor = theme.text.secondary; // Or theme.text.secondary
90	                icon = '🔍'; // Left-pointing magnifying glass (🔍)
91	                break;
92	              case 'log':
93	              default:
94	                // Default textColor and icon are already set
95	                break;
96	            }
97	
98	            return (
99	              <Box flexDirection="row">
100	                <Box minWidth={iconBoxWidth} flexShrink={0}>
101	                  <Text color={textColor}>{icon}</Text>
102	                </Box>
103	                <Text color={textColor} wrap="wrap">
104	                  {msg.content}
105	                  {msg.count && msg.count > 1 && (
106	                    <Text color={theme.text.secondary}> (x{msg.count})</Text>
107	                  )}
108	                </Text>
109	              </Box>
110	            );
111	          }}
112	          keyExtractor={(item, index) => `${item.content}-${index}`}
113	          estimatedItemHeight={estimatedItemHeight}
114	          hasFocus={hasFocus}
115	          initialScrollIndex={Number.MAX_SAFE_INTEGER}
116	        />
117	      </Box>
118	    </Box>
119	  );
120	};
