import type { LoadedSettings } from '../../config/settings.js';

export type ErrorVerbosity = 'low' | 'full';

/**
 * Resolves the effective error verbosity.
 *
 * In "low" verbosity mode (the default), transient/recoverable error indicators
 * are suppressed. In "full" verbosity mode all detailed behaviors are retained.
 * Debug mode always behaves as "full" verbosity.
 */
export function getErrorVerbosity(
  settings: LoadedSettings,
  debugMode = false,
): ErrorVerbosity {
  if (debugMode) {
    return 'full';
  }
  return settings.merged.ui?.errorVerbosity ?? 'low';
}
